css:
*{box-sizing:border-box;margin:0;padding:0}
.pop{width:1055px;height:1491px;overflow:hidden}
.pop{font-family:"Hiragino Sans","Hiragino Kaku Gothic ProN",sans-serif;color:#1b2550;position:relative;
  background:
   radial-gradient(circle,rgba(255,255,255,.75) 2.4px,transparent 2.9px) 0 0/26px 26px,
   radial-gradient(circle,rgba(255,255,255,.5) 1.6px,transparent 2px) 13px 13px/26px 26px,
   linear-gradient(180deg,#9fdcff 0%,#c8ecff 45%,#e6f6ff 100%)}
i{font-style:normal;display:inline-block}
em{font-style:normal}
/* 題字 */
.store{position:absolute;left:0;right:0;top:10px;text-align:center}
.store span{display:inline-block;background:#1b2550;color:#fff;font-weight:900;font-size:30px;padding:2px 30px 4px;border-radius:30px;border:4px solid #fff}
.title{position:absolute;left:0;right:0;top:62px;text-align:center;font-weight:900;font-size:108px;line-height:1;letter-spacing:2px;
  color:#fff;-webkit-text-stroke:14px #1b2550;paint-order:stroke fill;text-shadow:7px 8px 0 #1b2550}
.title .f{color:#7fd3ff}
.title .r{color:#ffde3a}
.five{position:absolute;left:50%;top:186px;transform:translateX(-50%) rotate(-2deg);background:#ff4d4d;color:#fff;font-weight:900;font-size:34px;
  padding:0 40px 4px;border-radius:40px;border:5px solid #1b2550;box-shadow:6px 6px 0 #1b2550;letter-spacing:6px;white-space:nowrap}
.five b{color:#ffe066;font-size:42px}
.snow{position:absolute;color:#fff;font-size:44px;text-shadow:2px 3px 0 #1b2550}
/* 箱 */
.card{position:absolute;background:#fff;border:5px solid #1b2550;border-radius:26px;box-shadow:7px 7px 0 #1b2550;overflow:hidden}
.hd{height:60px;display:flex;align-items:center;gap:10px;padding:0 16px;border-bottom:5px solid #1b2550;color:#fff;font-weight:900;font-size:31px;white-space:nowrap}
.hd .no{flex:none;width:42px;height:42px;border-radius:50%;background:#fff;color:#1b2550;font:900 28px/36px "Arial Black";text-align:center;border:3px solid #1b2550}
.bd{padding:10px 18px}
.c1 .hd{background:#ff7a3d}.c2 .hd{background:#ff5c95}.c3 .hd{background:#2fb35a}.c4 .hd{background:#2f8ff0}.c5 .hd{background:#8a63ff}
.note{font-size:17.5px;font-weight:700;color:#3a4470;line-height:1.45}
.big{font-weight:900;color:#e8442c}
/* ① */
.c1 .lead{text-align:center;font-weight:900;font-size:27px}
.c1 .lead .big{font-size:44px}
.two{display:flex;gap:10px;margin:8px 0 8px}
.two>div{flex:1;border-radius:18px;border:4px solid #1b2550;text-align:center;padding:4px 0 6px}
.two .a{background:#fff1b0}.two .b{background:#e3f3ff}
.two small{display:inline-block;font-weight:900;font-size:19px;background:#1b2550;color:#fff;border-radius:14px;padding:0 12px;margin-bottom:2px}
.two b{display:block;font-size:40px;font-weight:900;color:#1b2550;line-height:1.1}
.two span{font-size:18px;font-weight:800}
/* ② */
.tag{display:inline-block;font-weight:900;font-size:20px;background:#ffe066;border:3px solid #1b2550;border-radius:14px;padding:0 12px}
.blk{padding:4px 0 5px;border-bottom:3px dotted #c9cfe0}
.blk p{font-size:19px;font-weight:800;margin-top:3px}
.blk .tk{font-size:36px;font-weight:900;color:#e8442c;line-height:1.1}
.blk .tk small{font-size:26px}
/* ③④ */
.lg{height:74px;display:flex;align-items:center;justify-content:center;background:#fff;border-bottom:5px solid #1b2550;position:relative}
.c3 .lg{background:#2fb35a}.c4 .lg{background:#2f8ff0}
.lg img{height:62px}
.lg .no{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:44px;height:44px;border-radius:50%;background:#fff;color:#1b2550;font:900 28px/38px "Arial Black";text-align:center;border:3px solid #1b2550}
.new{position:absolute;right:10px;top:8px;background:#ffe066;color:#e8442c;font-weight:900;font-size:19px;border:3px solid #1b2550;border-radius:16px;padding:0 10px;transform:rotate(10deg)}
.free{text-align:center;font-weight:900;font-size:44px;color:#e8442c;line-height:1.1}
.hit{text-align:center;margin:4px 0 6px}
.hit span{display:inline-block;font-weight:900;font-size:25px;border-radius:30px;padding:2px 18px;border:4px solid #1b2550}
.c3 .hit span{background:#fff1b0}.c4 .hit span{background:#e3f3ff;color:#1667c8}
.ls{list-style:none}
.ls li{font-size:21.5px;font-weight:800;line-height:1.35;padding:6px 0 6px 26px;position:relative;border-top:2px dotted #c9cfe0}
.ls li:before{content:"●";position:absolute;left:4px;top:8px;font-size:15px}
.c3 .ls li:before{color:#2fb35a}.c4 .ls li:before{color:#2f8ff0}
.pill{display:inline-block;background:#e8442c;color:#fff;font-weight:900;border-radius:16px;padding:0 12px}
.catch4{text-align:center;font-weight:900;font-size:22px;color:#fff;background:#e8442c;border-radius:20px;padding:3px 8px;margin:4px 0 6px;border:3px solid #1b2550}
/* ⑤ */
.c5 .bd{display:flex;gap:16px;padding:10px 16px}
.c5 .l{flex:1.05}.c5 .r{flex:1;border-left:3px dotted #c9cfe0;padding-left:16px}
.rk{display:flex;align-items:center;gap:8px;font-size:23px;font-weight:800;padding:5px 0;border-bottom:2px dotted #c9cfe0}
.rk b{flex:none;width:32px;height:32px;border-radius:50%;color:#1b2550;font:900 19px/26px "Arial Black";text-align:center;border:3px solid #1b2550}
.rk:nth-of-type(1) b{background:#ffd23a}.rk:nth-of-type(2) b{background:#dfe3ea}.rk:nth-of-type(3) b{background:#e6a66a}
.pass{margin-top:12px;font-size:21px;font-weight:800}
.pass b{display:inline-block;font-size:38px;font-weight:900;color:#8a63ff;line-height:1.15}
.pt li{font-size:19px;gap:10px;font-weight:800;padding:6px 0;list-style:none;display:flex;justify-content:space-between;border-bottom:2px dotted #c9cfe0}
.pt li span:last-child{color:#e8442c;font-weight:900;white-space:nowrap}
.pt li span:first-child{white-space:nowrap}
.c5 .note{margin-top:8px;font-size:17.5px;line-height:1.45}

/* 読みやすさ優先の上書き */
.pop{background:linear-gradient(180deg,#bfe6ff 0%,#dff2ff 40%,#eef8ff 100%)!important}
.card{border-width:4px!important;box-shadow:4px 4px 0 #1b2550!important;border-radius:20px!important}
.title{text-shadow:5px 6px 0 #1b2550!important}
.hd{font-size:33px!important;height:62px!important}
/* ① */
.c1 .lead{font-size:31px!important;margin-top:2px}
.c1 .lead .big{font-size:54px!important}
.two{margin:6px 0 8px!important}
.two small{font-size:22px!important}
.two b{font-size:54px!important}
.two span{font-size:22px!important}
.c1 .note{font-size:21px!important;line-height:1.4}
/* ② */
.tag{font-size:22px!important}
.blk p{font-size:24px!important;line-height:1.25}
.blk .tk{font-size:48px!important}
.blk .tk small{font-size:32px!important}
.c2 .note{font-size:20px!important}
/* ③④ */
.lg{height:72px!important}
.free{font-size:50px!important}
.hit span{font-size:29px!important}
.catch4{font-size:25px!important}
.ls li{font-size:24.5px!important;padding:5px 0 5px 26px!important;line-height:1.3!important}
.ls li:before{top:7px!important}
.pill{font-size:23px}
/* ⑤ */
.c5 .hd{height:58px!important}
.rk{font-size:26px!important;padding:5px 0!important}
.rk b{width:36px!important;height:36px!important;font:900 21px/30px "Arial Black"!important}
.pass{font-size:24px!important}
.pass b{font-size:46px!important}
.pt li{font-size:22px!important;padding:5px 0!important}
.c5 .note{font-size:20px!important;line-height:1.4!important}

.store{top:6px!important}.store span{font-size:26px!important;padding:0 26px 2px!important}
.title{top:46px!important;font-size:96px!important;-webkit-text-stroke:12px #1b2550!important}
.five{top:160px!important;font-size:30px!important;padding:0 34px 3px!important}
.five b{font-size:36px!important}
.snow{display:none}
.ls li{font-size:23.5px!important}
.catch4{font-size:22.5px!important;white-space:nowrap}
.c5 .l{flex:1.12!important}
.rk{font-size:23.5px!important;white-space:nowrap}
.pass b{font-size:42px!important}
.pass{margin-top:8px!important}
.pt li{font-size:20.5px!important}
.c5 .note{font-size:18.5px!important}
.c5 .bd{padding:8px 16px!important}

.c1 .lead{font-size:29px!important}.c1 .lead .big{font-size:48px!important}
.two{margin:4px 0 6px!important}.two b{font-size:48px!important}.two small{font-size:20px!important}.two span{font-size:20px!important}
.c1 .note{font-size:19.5px!important;line-height:1.35!important}
.blk{padding:3px 0 4px!important}.blk p{font-size:22px!important}.blk .tk{font-size:42px!important}.blk .tk small{font-size:29px!important}
.c2 .note{font-size:19px!important;margin-top:4px!important}
.ls li{font-size:22.5px!important}
.pass b{font-size:36px!important}
.rk{padding:4px 0!important}
.pass b{font-size:33px!important}
.pass{white-space:nowrap}
.c5 .l{flex:none!important;width:470px}
.c5 .r{min-width:0}
.pt li{font-size:19.5px!important}
.ls li{font-size:22.5px!important;padding:7px 0 7px 26px!important}

.store{top:0!important;z-index:2}.store span{font-size:24px!important}
.title{top:38px!important;font-size:150px!important;letter-spacing:0!important;-webkit-text-stroke:16px #1b2550!important;text-shadow:6px 7px 0 #1b2550!important}
.five{top:196px!important;font-size:28px!important;z-index:2}
.five b{font-size:34px!important}
.c1 .note{font-size:19px!important}
.ls li{padding:6px 0 6px 26px!important}

.store{top:8px!important}.store span{font-size:24px!important;padding:0 24px 2px!important;border-width:3px!important}
.title{top:50px!important;font-size:136px!important;letter-spacing:12px!important;-webkit-text-stroke:8px #1b2550!important;text-shadow:4px 5px 0 #1b2550!important;line-height:1!important}
.five{top:194px!important}

.title{top:60px!important;font-size:132px!important;letter-spacing:14px!important;-webkit-text-stroke:7px #1b2550!important;text-shadow:none!important}
.store{top:6px!important}
.five{top:200px!important}
.pop{background:url(snowbg.png) center top/cover no-repeat #dff2ff!important}

/* 色を4色にしぼる：紺・白・赤・黄 */
.c1 .hd,.c2 .hd,.c5 .hd,.c3 .lg,.c4 .lg{background:#1b2550!important}
.hd .no,.lg .no{background:#ffd23a!important}
.two .a,.two .b{background:#fff!important}
.c3 .hit span,.c4 .hit span{background:#fff!important;color:#1b2550!important}
.c4 .hit span{color:#1b2550!important}
.c3 .ls li:before,.c4 .ls li:before{color:#e8442c!important}
.pass b{color:#e8442c!important}
.rk:nth-of-type(1) b,.rk:nth-of-type(2) b,.rk:nth-of-type(3) b{background:#ffd23a!important}
.title .f{color:#fff!important}
.tag{background:#ffd23a!important}

/* 強弱：大事な所は大きく、説明は小さく */
.c1 .lead{font-size:30px!important}.c1 .lead .big{font-size:60px!important}
.two b{font-size:60px!important}.two small{font-size:20px!important}.two span{font-size:20px!important}
.c1 .note{font-size:16px!important;margin-top:4px}
.blk p{font-size:18px!important}.blk .tk{font-size:58px!important}.blk .tk small{font-size:34px!important}
.c2 .note{font-size:15.5px!important}
.free{font-size:64px!important;line-height:1.05!important}
.hit{margin:6px 0 4px!important}.hit span{font-size:30px!important;padding:2px 20px!important}
.hit .big{font-size:36px}
.first{text-align:center;margin:2px 0 6px}.first span{display:inline-block;background:#e8442c;color:#fff;font-weight:900;font-size:28px;border-radius:24px;padding:0 22px 2px;border:3px solid #1b2550}
.catch4{font-size:22px!important;margin:4px 0 8px!important}
.ls li{font-size:17.5px!important;padding:5px 0 5px 22px!important;line-height:1.35!important;font-weight:700!important}
.ls li:before{font-size:12px!important;top:7px!important}
.rk{font-size:25px!important;padding:6px 0!important}
.pass b{font-size:48px!important}.pass{font-size:20px!important}
.pt li{font-size:18px!important;padding:4px 0!important}
.c5 .note{font-size:15.5px!important;line-height:1.45!important}

.c1 .lead .big{font-size:54px!important}
.two b{font-size:52px!important}
.c1 .note{font-size:15px!important;line-height:1.3!important;margin-top:2px!important}
.blk .tk{font-size:50px!important}.blk .tk small{font-size:30px!important}
.blk{padding:2px 0 3px!important}
.c2 .note{font-size:15px!important;margin-top:2px!important}
.c4 .hit span,.c3 .hit span{font-size:26px!important;padding:2px 16px!important;white-space:nowrap}
.hit .big{font-size:32px!important}
.free{font-size:58px!important}
.pass b{font-size:42px!important}
.pass{white-space:nowrap}
.pass b{font-size:36px!important}
.pass span{font-size:17px!important}

/* 枠ごとの主役 */
.blk .tk3{font-size:38px!important}.blk .tk3 small{font-size:24px!important}
.free-s{font-size:30px!important;margin-bottom:2px}
.hero4{text-align:center;font-weight:900;font-size:36px;line-height:1.2;color:#fff;background:#e8442c;border:4px solid #1b2550;border-radius:22px;padding:8px 6px 10px;margin:4px 0 8px}
.rk1{padding:4px 0 8px!important}
.rk1 b{width:44px!important;height:44px!important;font:900 26px/38px "Arial Black"!important}
.rk1 .h1{font-size:40px;font-weight:900;color:#e8442c}
.rk1 .h1s{font-size:20px}
.pass b{font-size:28px!important}
.pass span{font-size:16px!important}
.pass{font-size:18px!important}

.c3 .hit span,.c4 .hit span{font-size:22px!important;padding:1px 14px!important}
.hit .big{font-size:26px!important}
.first span{font-size:22px!important}
.hero4{font-size:33px!important;padding:6px 6px 8px!important;margin:4px 0 4px!important}
.c4 .ls li{padding:4px 0 4px 22px!important}
.c3 .free{font-size:66px!important}

/* 店名なし・題字と5大特典を一体に */
.title{top:22px!important;font-size:150px!important;letter-spacing:8px!important}
.five{top:192px!important;font-size:32px!important;padding:2px 44px 6px!important}
.five b{font-size:40px!important}
.five{transform:translateX(-50%)!important;top:190px!important}

/* ===== パチンコ店・メダルコーナー寄り：黒×金×赤 ===== */
.pop{background:
  radial-gradient(ellipse at 50% 12%,rgba(255,196,80,.38) 0,rgba(255,196,80,0) 45%),
  repeating-conic-gradient(from 0deg at 50% 12%,rgba(255,210,120,.10) 0deg 4deg,rgba(0,0,0,0) 4deg 12deg),
  radial-gradient(circle at 50% 30%,#2a1a06 0,#0b0704 70%)!important}
body:after{content:"";position:absolute;inset:0;pointer-events:none;z-index:0;background:
  radial-gradient(circle,rgba(255,230,160,.95) 1.3px,transparent 2.4px) 0 0/64px 76px,
  radial-gradient(circle,rgba(255,255,255,.8) 1px,transparent 2px) 32px 38px/92px 84px;opacity:.45}
.card,.title,.five{z-index:1}.five{z-index:5!important}
/* 題字：金の立体文字＋光 */
.title{top:26px!important;font-size:146px!important;letter-spacing:8px!important;-webkit-text-stroke:0!important;
  color:transparent!important;background:linear-gradient(180deg,#fff8d6 0%,#ffe08a 22%,#d9a63a 48%,#a8731c 52%,#e9c25e 75%,#fff1b8 100%);-webkit-background-clip:text;background-clip:text;
  text-shadow:none!important;
  filter:drop-shadow(0 2px 0 #5a3a08) drop-shadow(0 4px 0 #3a2404) drop-shadow(0 0 3px #1a0e00) drop-shadow(0 0 18px rgba(255,190,60,.55))}
.title .f{background:linear-gradient(180deg,#ffffff 0%,#e8f4ff 40%,#9fb8d0 52%,#f2f8ff 78%,#ffffff 100%);-webkit-background-clip:text;background-clip:text;color:transparent!important}
.title .r{color:transparent!important}
/* 5大特典：赤い札＋金のフチ */
.five{top:196px!important;transform:translateX(-50%)!important;background:linear-gradient(180deg,#e0213a,#8a0a1c)!important;
  border:4px solid #e2b34e!important;box-shadow:0 0 0 2px #2a1400,0 0 20px rgba(255,80,60,.45)!important;border-radius:12px!important;
  color:#fff!important;-webkit-text-stroke:0!important;font-size:32px!important;padding:0 42px 4px!important}
.five b{color:#ffe08a!important;font-size:40px!important}
/* 箱：黒の板＋金のフチ */
.card{background:linear-gradient(180deg,#1a1410 0%,#0d0a08 100%)!important;color:#fff!important;
  border:5px solid transparent!important;
  background-image:linear-gradient(180deg,#1c1611,#0b0806),linear-gradient(180deg,#fff8d6 0%,#ffe08a 22%,#d9a63a 48%,#a8731c 52%,#e9c25e 75%,#fff1b8 100%)!important;background-origin:border-box!important;background-clip:padding-box,border-box!important;
  box-shadow:0 0 0 2px #000,0 10px 24px rgba(0,0,0,.6)!important;border-radius:18px!important}
.c1 .hd,.c2 .hd,.c5 .hd{background:linear-gradient(180deg,#e0213a 0%,#a10c22 55%,#7a0618 100%)!important;border-bottom:3px solid #e2b34e!important;color:#fff!important;text-shadow:0 2px 0 #3a0008!important}
.c3 .lg{background:linear-gradient(180deg,#1d7a48,#0c4126)!important;border-bottom:3px solid #e2b34e!important}
.c4 .lg{background:linear-gradient(180deg,#2457b8,#0f2a66)!important;border-bottom:3px solid #e2b34e!important}
.hd .no,.lg .no{background:linear-gradient(180deg,#fff8d6 0%,#ffe08a 22%,#d9a63a 48%,#a8731c 52%,#e9c25e 75%,#fff1b8 100%)!important;border-color:#5a3a08!important;color:#3a1a00!important}
.note,.c2 .note,.c1 .note,.c5 .note{color:#cfc6b4!important}
.ls li,.pt li,.rk,.blk p,.c1 .lead,.pass,.pass2{color:#fff!important}
.ls li,.pt li,.rk,.blk{border-color:rgba(226,179,78,.35)!important}
.c5 .r{border-color:rgba(226,179,78,.4)!important}
/* 数字：金のメッキ */
.big,.blk .tk,.two b,.rk1 .h1,.pass b,.free{color:transparent!important;background:linear-gradient(180deg,#fff8d6 0%,#ffe08a 22%,#d9a63a 48%,#a8731c 52%,#e9c25e 75%,#fff1b8 100%);-webkit-background-clip:text;background-clip:text;-webkit-text-stroke:0!important;text-shadow:none!important;
  filter:drop-shadow(0 2px 0 #4a2c04) drop-shadow(0 0 10px rgba(255,190,60,.35))}
.blk .tk small{font-size:inherit}
.two>div{background:rgba(255,255,255,.04)!important;border:3px solid #e2b34e!important}
.two small{background:#a10c22!important;color:#fff!important}
.two span{color:#fff}
.hit span{background:transparent!important;border:3px solid #e2b34e!important;color:#fff!important}
.c3 .hit span,.c4 .hit span{background:transparent!important;color:#fff!important}
.hero4{background:linear-gradient(180deg,#e0213a,#7a0618)!important;border:3px solid #e2b34e!important;color:#fff!important;box-shadow:0 0 18px rgba(255,60,60,.35)!important}
.first span,.pill{background:linear-gradient(180deg,#e0213a,#7a0618)!important;border-color:#e2b34e!important}
.tag{background:linear-gradient(180deg,#fff8d6 0%,#ffe08a 22%,#d9a63a 48%,#a8731c 52%,#e9c25e 75%,#fff1b8 100%)!important;border-color:#5a3a08!important;color:#2a1400!important}
.new{background:linear-gradient(180deg,#fff8d6 0%,#ffe08a 22%,#d9a63a 48%,#a8731c 52%,#e9c25e 75%,#fff1b8 100%)!important;color:#a10c22!important;border-color:#5a3a08!important}
.ls li:before,.c3 .ls li:before,.c4 .ls li:before{color:#e2b34e!important}
.pt li span:last-child{color:#ffd36a!important}
.rk b,.rk:nth-of-type(1) b,.rk:nth-of-type(2) b,.rk:nth-of-type(3) b{background:linear-gradient(180deg,#fff8d6 0%,#ffe08a 22%,#d9a63a 48%,#a8731c 52%,#e9c25e 75%,#fff1b8 100%)!important;border-color:#5a3a08!important}
.rk1 .h1s,.rk span{color:#fff}
.lg{border-bottom-width:3px!important}
.two .a,.two .b{background:rgba(255,255,255,.05)!important}.two span{color:#fff!important}
.pass{margin-top:2px!important}.c5 .rk{padding:3px 0!important}
